//! A quote a day: a screen in the tools menu with a short quote about
//! reading, a different one each day of the year.

#![no_std]

extern crate alloc;

use alloc::borrow::Cow;
use alloc::boxed::Box;

use paperpaw_sdk::builtin::{actions, menus};
use paperpaw_sdk::time;
use paperpaw_sdk::ui::{self, UiStyle};
use paperpaw_sdk::{
    ActionSpec, Canvas, Command, Cx, Env, Gesture, GestureKind, Handled, Id, Manifest, MenuEntry,
    Params, Plugin, Rect, RegisterError, Registrar, Screen, ScreenSpec, Version,
};

pub const PLUGIN: Id = Id::new_static("quote");
pub const OPEN: Id = Id::new_static("quote.open");
pub const SCREEN: Id = Id::new_static("quote.screen");

/// The quotes, one a day in turn.
const QUOTES: &[&str] = &[
    "Well begun is half done.\n(Aristotle)",
    "Reading is to the mind what exercise is to the body.\n(Joseph Addison)",
    "Books are the quietest and most constant of friends.\n(Charles W. Eliot)",
    "A room without books is like a body without a soul.\n(after Cicero)",
    "The secret of getting ahead is getting started.\n(after Mark Twain)",
    "No two persons ever read the same book.\n(Edmund Wilson)",
    "Once you learn to read, you will be forever free.\n(Frederick Douglass)",
];

#[derive(Debug, Default)]
pub struct QuoteOfTheDay;

impl Plugin for QuoteOfTheDay {
    fn manifest(&self) -> Manifest {
        Manifest::new(PLUGIN, "Quote of the day", Version::new(0, 1, 0))
            .description("A short quote about reading, a different one each day.")
            .uses(paperpaw_sdk::Uses::NOTHING)
    }

    fn register(&self, r: &mut Registrar) -> Result<(), RegisterError> {
        r.add_action(ActionSpec::new(OPEN, "quote.title").handler(|_, out| {
            out.push(Command::OpenScreen(SCREEN, Params::new()));
        }))?;
        r.add_menu_entry(MenuEntry::new(menus::TOOLS, OPEN).order(90))?;
        r.add_icon(OPEN, Cow::Borrowed("star"))?;
        r.add_screen(ScreenSpec::new(
            SCREEN,
            "quote.title",
            Box::new(|env, _| Box::new(QuoteScreen::new(env))),
        ))?;
        r.add_translations(Cow::Borrowed(include_str!("../i18n/en.ini")))?;
        r.add_translations(Cow::Borrowed(include_str!("../i18n/de.ini")))?;
        Ok(())
    }
}

/// Today's quote: the day of the year picks it; without a clock, the first.
fn today(env: &Env<'_>) -> &'static str {
    let day = time::local_time(env).map_or(0, |t| t.day_of_year);
    QUOTES[usize::from(day) % QUOTES.len()]
}

struct QuoteScreen {
    style: UiStyle,
    header: ui::Header,
}

impl QuoteScreen {
    fn new(env: &Env<'_>) -> Self {
        let style = UiStyle::new(env);
        Self {
            header: ui::Header::new(env, &style, true),
            style,
        }
    }
}

impl Screen for QuoteScreen {
    fn draw(&mut self, canvas: &mut Canvas<'_>, env: &Env<'_>) {
        let title = env.i18n.tr("quote.title");
        self.header.draw(canvas, env, &self.style, title, None, None);
        let display = env.device.display;
        let top = self.header.area.height;
        let area = Rect::new(0, top, display.width, display.height.saturating_sub(top));
        ui::draw_message(canvas, env, &self.style, area, today(env));
    }

    fn on_action(&mut self, action: &Id, cx: &mut Cx<'_, '_>) -> Handled {
        if *action == actions::CONFIRM || *action == actions::BACK {
            cx.command(Command::Back);
            return Handled::Yes;
        }
        Handled::No
    }

    fn on_gesture(&mut self, gesture: Gesture, cx: &mut Cx<'_, '_>) -> Handled {
        if gesture.kind != GestureKind::Tap {
            return Handled::No;
        }
        if let Some(action) = self.header.tap(cx.env(), &self.style, gesture.start, None) {
            cx.command(Command::RunAction(action));
        } else {
            cx.command(Command::Back);
        }
        Handled::Yes
    }
}

